INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('become-a-foster-parent','process','zigzag','{"reverse": true, "heading": "Interview / Initial Home Survey", "body": "<p>We begin with an interview and home visit to get to know you and assess the environment where you\u2019ll be fostering. This informal survey helps us understand your motivation for fostering and ensures your home meets the basic safety requirements.</p>", "img": {"avif": "/assets/uploads/2024/10/Frame-34130-2-640.avif 640w", "webp": "/assets/uploads/2024/10/Frame-34130-2-640.webp 640w", "jpg": "/assets/uploads/2024/10/Frame-34130-2.jpg", "w": "834", "h": "468"}}',0,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('become-a-foster-parent','process','zigzag','{"reverse": true, "heading": "Complete and Submit Application Documents", "body": "<p>Next, you\u2019ll complete the required application forms, which include background checks, references, and other important documentation. This step ensures that all necessary legal and safety requirements are met.</p>", "img": {"avif": "/assets/uploads/2024/10/Frame-34130-3-640.avif 640w", "webp": "/assets/uploads/2024/10/Frame-34130-3-640.webp 640w", "jpg": "/assets/uploads/2024/10/Frame-34130-3.jpg", "w": "834", "h": "468"}}',1,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('become-a-foster-parent','process','zigzag','{"reverse": true, "heading": "Home Study (Structured Analysis Family Evaluation)", "body": "<p>A thorough evaluation of your household is conducted through the Home Study process. This involves interviews, assessments, and home inspections to ensure your family is fully prepared to foster. The study helps us match you with the right child based on your strengths and family dynamics.</p>", "img": {"avif": "/assets/uploads/2024/10/Frame-34130-1-e1730335908622-640.avif 640w", "webp": "/assets/uploads/2024/10/Frame-34130-1-e1730335908622-640.webp 640w", "jpg": "/assets/uploads/2024/10/Frame-34130-1-e1730335908622.jpg", "w": "828", "h": "464"}}',2,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('become-a-foster-parent','process','zigzag','{"reverse": true, "heading": "", "body": "<p>Once your application and home study are complete, you\u2019ll participate in our comprehensive foster parent training. This training covers topics such as trauma-informed care, child development, and behaviour management to equip you with the skills and knowledge needed to provide exceptional care.</p>", "img": {"avif": "/assets/uploads/2024/10/Frame-34130-4-640.avif 640w", "webp": "/assets/uploads/2024/10/Frame-34130-4-640.webp 640w", "jpg": "/assets/uploads/2024/10/Frame-34130-4.jpg", "w": "834", "h": "468"}}',3,'published','');
